#!/usr/bin/env python3
"""Actual EFI RNG seed capture, post-EBS DRBG and secure-source absence."""
import argparse,json,pathlib,shutil,sys
sys.path.insert(0,str(pathlib.Path(__file__).parent))
from qemu_platform import Guest,wait
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--out',type=pathlib.Path,required=True);p.add_argument('--missing',action='store_true');o=p.parse_args()
out=o.out.resolve();out.mkdir(parents=True,exist_ok=False);disk=out/'disposable.img';shutil.copyfile('build/qemu-smoke-disk.img',disk)
a=argparse.Namespace(mode='uefi',kernel=pathlib.Path('build/chos.elf'),uefi_kernel=pathlib.Path('build/uefi-kernel/chos.elf'),iso=pathlib.Path('build/chos-0.30.0.iso'),memory='2G',qemu_data=pathlib.Path('/workspace/chos-tools/root/usr/share/qemu'),rtc_base=None,trace=False,firmware=pathlib.Path('/workspace/chos-tools/root/usr/share/AAVMF/AAVMF_CODE.fd'),no_usb=False,usb_pci_bus=0,xhci_model='qemu-xhci',pci_virtio=True,net_model='e1000e',storage_error=False,nvme=False,no_rng=o.missing,hub_depth=0,empty_usb=False,tablet=True)
g=Guest(a,out,disk)
try:
 wait(lambda:'chos> ' in g.text(),45,'actual UEFI runtime')
 marker='Firmware RNG seed consumed and erased; bounded HMAC-DRBG available.'
 assert (marker in g.text())!=o.missing,'actual firmware source availability differs from requested profile'
 g.serial('rng-firmware-test')
 expected='[FAIL] Firmware-seeded entropy unavailable or boot budget exhausted.' if o.missing else '[ OK ] Firmware-seeded HMAC-DRBG generated 32 bytes; sample erased.'
 wait(lambda:expected in g.text(),4,'post-EBS actual firmware DRBG result')
 g.serial('rng-test')
 expected_public='[FAIL] RNG hardware bytes unavailable' if o.missing else '[ OK ] RNG received 32 hardware bytes'
 wait(lambda:expected_public in g.text(),5,'retained public entropy service')
 assert '[FATAL]' not in g.text()
 (out/'result.json').write_text(json.dumps({'status':'PASS','missing_source':o.missing,'checks':['actual EFI firmware RNG availability before ExitBootServices','post-handoff firmware-seeded HMAC-DRBG generated bytes or refused absence','retained public VirtIO entropy service behavior','no generated entropy bytes logged'],'limits':['QEMU AAVMF evidence; Fusion firmware RNG availability NOT RUN','not TLS, CA policy or modern browser qualification']},indent=2))
finally:g.close()
